// Simulate temperature drift based on HVAC running state
var z1Running = Globals.ReadBool("Zone1_Office.Running");
var z1Temp = Globals.ReadDouble("Zone1_Office.Temperature");
var z1Sp = Globals.ReadDouble("Zone1_Office.Setpoint");
var drift1 = z1Running ? (z1Sp - z1Temp) * 0.05 : (24.0 - z1Temp) * 0.02;
Globals.Write("Zone1_Office.Temperature", z1Temp + drift1 + (new Random().NextDouble() - 0.5) * 0.3);

var z2Running = Globals.ReadBool("Zone2_Workshop.Running");
var z2Temp = Globals.ReadDouble("Zone2_Workshop.Temperature");
var z2Sp = Globals.ReadDouble("Zone2_Workshop.Setpoint");
var drift2 = z2Running ? (z2Sp - z2Temp) * 0.04 : (26.0 - z2Temp) * 0.015;
Globals.Write("Zone2_Workshop.Temperature", z2Temp + drift2 + (new Random().NextDouble() - 0.5) * 0.4);

var z3Running = Globals.ReadBool("Zone3_ServerRoom.Running");
var z3Temp = Globals.ReadDouble("Zone3_ServerRoom.Temperature");
var z3Sp = Globals.ReadDouble("Zone3_ServerRoom.Setpoint");
var drift3 = z3Running ? (z3Sp - z3Temp) * 0.06 : (30.0 - z3Temp) * 0.03;
Globals.Write("Zone3_ServerRoom.Temperature", z3Temp + drift3 + (new Random().NextDouble() - 0.5) * 0.2);

// Calculate total power based on running equipment
var power = 0.0;
if (Globals.ReadBool("Zone1_Office.Running")) power += 12.0 + Globals.ReadDouble("Zone1_Office.FanSpeed") * 0.05;
if (Globals.ReadBool("Zone2_Workshop.Running")) power += 18.0 + Globals.ReadDouble("Zone2_Workshop.FanSpeed") * 0.08;
if (Globals.ReadBool("Zone3_ServerRoom.Running")) power += 25.0;
if (Globals.ReadBool("Compressor_Enable")) power += 45.0;
if (Globals.ReadBool("WaterPump_Enable")) power += 8.0;
if (Globals.ReadBool("Office_Lights")) power += 3.0 + Globals.ReadDouble("Office_Brightness") * 0.02;
if (Globals.ReadBool("Workshop_Lights")) power += 5.0 + Globals.ReadDouble("Workshop_Brightness") * 0.03;
if (Globals.ReadBool("Parking_Lights")) power += 2.0;
if (Globals.ReadBool("SecurityLights")) power += 1.5;
power += (new Random().NextDouble() - 0.5) * 2.0;
Globals.Write("TotalPower_kW", Math.Max(0, power));
Globals.Write("Compressor_Power_kW", Globals.ReadBool("Compressor_Enable") ? 45.0 + (new Random().NextDouble() - 0.5) * 3.0 : 0.0);
var daily = Globals.ReadDouble("DailyEnergy_kWh");
Globals.Write("DailyEnergy_kWh", daily + power * 10.0 / 3600.0);
